# Passkeys in integration tests (generated by maquina:passkeys).
#
# WebAuthn::FakeClient plays the browser and the authenticator, so tests go
# through the real endpoints: register_passkey needs a signed-in user
# (sign_in_as), sign_in_with_passkey needs a passkey the same client made.
#
#   sign_in_as users(:one)
#   register_passkey
#   sign_out
#   sign_in_with_passkey(users(:one))
#   assert_response :success
require "webauthn/fake_client"

module WebauthnTestHelper
  def webauthn_client
    @webauthn_client ||= WebAuthn::FakeClient.new(WebAuthn.configuration.allowed_origins.first)
  end

  def register_passkey(client: webauthn_client)
    post passkey_challenge_path, as: :json
    credential = client.create(challenge: response.parsed_body["challenge"], rp_id: WebAuthn.configuration.rp_id,
      user_verified: true)

    post passkeys_path, params: {credential: credential}, as: :json
  end

  def sign_in_with_passkey(user, client: webauthn_client)
    post session_passkey_challenge_path, as: :json
    assertion = client.get(challenge: response.parsed_body["challenge"], rp_id: WebAuthn.configuration.rp_id,
      user_verified: true, user_handle: Base64.urlsafe_decode64(user.reload.webauthn_id))

    post session_passkey_path, params: {credential: assertion}, as: :json
  end
end

ActiveSupport.on_load(:action_dispatch_integration_test) do
  include WebauthnTestHelper
end
